import{_ as t,o as a,c as i,ae as r}from"./chunks/framework.1Lna8NcP.js";const p=JSON.parse('{"title":"Libertas Pages Design Spec","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-04-05-libertas-pages-design.md","filePath":"superpowers/specs/2026-04-05-libertas-pages-design.md"}'),o={name:"superpowers/specs/2026-04-05-libertas-pages-design.md"};function s(l,e,n,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="libertas-pages-design-spec" tabindex="-1">Libertas Pages Design Spec <a class="header-anchor" href="#libertas-pages-design-spec" aria-label="Permalink to &quot;Libertas Pages Design Spec&quot;">​</a></h1><p><strong>Date:</strong> 2026-04-05 <strong>Scope:</strong> All 9 pages — Dashboard, Accounts, Import, Real Estate, Retirement, Insights, Debt, Taxes, Settings</p><hr><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Libertas is a locally-hosted personal finance dashboard. All data stays local. No cloud. No account linking.</p><hr><h2 id="_1-dashboard" tabindex="-1">1. Dashboard <a class="header-anchor" href="#_1-dashboard" aria-label="Permalink to &quot;1. Dashboard&quot;">​</a></h2><h3 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h3><p>The first thing seen each morning — a motivational, high-signal overview.</p><h3 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h3><ul><li><strong>Hero:</strong> Total net worth (large) + delta since yesterday (green/red)</li><li><strong>Motivational quote:</strong> Random daily quote from a curated finance/wealth-building list. Changes once per day.</li><li><strong>Accounts overview:</strong> Cards grouped by type (Investments, Cash, Crypto, Real Estate, Debt, Retirement). Each card shows account name, balance, staleness indicator (green &lt; 3 days, yellow 3–7 days, red &gt; 7 days).</li><li><strong>Top movers:</strong> Biggest gainers and losers across all holdings today (symbol, $ change, % change).</li><li><strong>News feed:</strong> Articles relevant to holdings and selected categories (Tech, Politics, Markets, Crypto). Source: RSS feeds (always on) + NewsAPI (when key configured in <code>.env</code>). Holdings-weighted — if user holds NVDA, NVDA news ranks higher.</li></ul><h3 id="news-feed-detail" tabindex="-1">News Feed Detail <a class="header-anchor" href="#news-feed-detail" aria-label="Permalink to &quot;News Feed Detail&quot;">​</a></h3><ul><li>NewsAPI key stored in <code>.env</code> as <code>NEWS_API_KEY</code>, never committed to git</li><li>RSS sources: Reuters, AP, Yahoo Finance (no key required, always available)</li><li>Filtering: holdings symbols extracted from DB + user-selected categories from Settings</li><li>Holdings-based results take priority over category results in display order</li><li>If NewsAPI key absent: RSS only, no error shown</li></ul><hr><h2 id="_2-accounts" tabindex="-1">2. Accounts <a class="header-anchor" href="#_2-accounts" aria-label="Permalink to &quot;2. Accounts&quot;">​</a></h2><h3 id="list-page" tabindex="-1">List Page <a class="header-anchor" href="#list-page" aria-label="Permalink to &quot;List Page&quot;">​</a></h3><ul><li>All accounts in a list with: name, type badge, current balance, last import date, staleness indicator (color-coded)</li><li><strong>One-click export link</strong> per account — opens the institution&#39;s export/login URL in the browser</li><li>Staleness color: green &lt; 3 days, yellow 3–7, red &gt; 7</li></ul><h3 id="account-detail-page-3-tabs" tabindex="-1">Account Detail Page (3 tabs) <a class="header-anchor" href="#account-detail-page-3-tabs" aria-label="Permalink to &quot;Account Detail Page (3 tabs)&quot;">​</a></h3><p><strong>Transactions tab</strong></p><ul><li>Full transaction history table</li><li>Filters (all active simultaneously): date range picker, transaction type multi-select (buy/sell/deposit/withdrawal/dividend/transfer), symbol/ticker search</li><li>Sortable columns</li></ul><p><strong>Holdings tab</strong></p><ul><li>Per holding: symbol, quantity, current value, gain/loss ($), gain/loss (%), % of account, cost basis</li><li>Sorted by value descending by default</li></ul><p><strong>Performance tab</strong></p><ul><li>Line chart of account balance over time</li><li>Default: All Time</li><li>Toggles: 1M / 3M / 6M / 1Y / All</li></ul><hr><h2 id="_3-import" tabindex="-1">3. Import <a class="header-anchor" href="#_3-import" aria-label="Permalink to &quot;3. Import&quot;">​</a></h2><h3 id="csv-detection" tabindex="-1">CSV Detection <a class="header-anchor" href="#csv-detection" aria-label="Permalink to &quot;CSV Detection&quot;">​</a></h3><ul><li>Default behavior: toast notification — &quot;143 new transactions from Fidelity — Import?&quot;</li><li>User can toggle to silent auto-import in Settings (no interruption)</li><li>Watch folder path configurable in Settings</li></ul><h3 id="new-institution-setup" tabindex="-1">New Institution Setup <a class="header-anchor" href="#new-institution-setup" aria-label="Permalink to &quot;New Institution Setup&quot;">​</a></h3><ul><li>Auto-detect column mapping from headers + sample rows</li><li>Show 3 sample rows of actual data for verification</li><li>Manual override toggle — user can switch to full manual mapping table if needed</li><li>Saved mapping reused on all subsequent imports from that institution</li></ul><h3 id="import-history-log" tabindex="-1">Import History Log <a class="header-anchor" href="#import-history-log" aria-label="Permalink to &quot;Import History Log&quot;">​</a></h3><ul><li>Columns: date, institution, file name, rows imported, duplicates skipped</li><li><strong>Undo/rollback</strong> — revert the most recent import (removes inserted transactions and restores previous balance snapshots)</li></ul><h3 id="institution-cards" tabindex="-1">Institution Cards <a class="header-anchor" href="#institution-cards" aria-label="Permalink to &quot;Institution Cards&quot;">​</a></h3><ul><li>Each institution shows: name, last import date, direct link to their export/login page</li><li>Quick access to institution management (same data as Settings &gt; Institutions)</li></ul><hr><h2 id="_4-real-estate" tabindex="-1">4. Real Estate <a class="header-anchor" href="#_4-real-estate" aria-label="Permalink to &quot;4. Real Estate&quot;">​</a></h2><h3 id="property-cards" tabindex="-1">Property Cards <a class="header-anchor" href="#property-cards" aria-label="Permalink to &quot;Property Cards&quot;">​</a></h3><ul><li>Hero number: <strong>Equity</strong> (value − mortgage balance)</li><li>Also shown: current estimated value (Zillow or override), mortgage balance, LTV %</li><li>Manual override field: user-entered value takes precedence over Zillow estimate when set</li><li>Zillow auto-refresh on demand</li></ul><h3 id="equity-over-time-chart" tabindex="-1">Equity Over Time Chart <a class="header-anchor" href="#equity-over-time-chart" aria-label="Permalink to &quot;Equity Over Time Chart&quot;">​</a></h3><ul><li>Per-property line chart tracking equity as Zillow estimate updates over time</li><li>X-axis: date of each Zillow refresh or manual value entry</li></ul><h3 id="multiple-properties" tabindex="-1">Multiple Properties <a class="header-anchor" href="#multiple-properties" aria-label="Permalink to &quot;Multiple Properties&quot;">​</a></h3><ul><li>Each property shown as its own card</li><li>No cross-property summary view</li></ul><hr><h2 id="_5-retirement" tabindex="-1">5. Retirement <a class="header-anchor" href="#_5-retirement" aria-label="Permalink to &quot;5. Retirement&quot;">​</a></h2><h3 id="north-star" tabindex="-1">North Star <a class="header-anchor" href="#north-star" aria-label="Permalink to &quot;North Star&quot;">​</a></h3><p>The user sets a target retirement date. The page answers: <strong>&quot;What do I need to retire by then, and am I on track?&quot;</strong></p><h3 id="retirement-target-setup" tabindex="-1">Retirement Target Setup <a class="header-anchor" href="#retirement-target-setup" aria-label="Permalink to &quot;Retirement Target Setup&quot;">​</a></h3><ul><li>User inputs a target retirement date (or age) in Settings &gt; User Profile</li><li>App calculates years remaining and required portfolio size using three methods shown simultaneously</li></ul><h3 id="target-display-3-views" tabindex="-1">Target Display (3 views) <a class="header-anchor" href="#target-display-3-views" aria-label="Permalink to &quot;Target Display (3 views)&quot;">​</a></h3><p>All three shown simultaneously so the user can understand their goal from multiple angles:</p><ol><li><strong>Fixed number</strong> — user sets a target portfolio value; app shows if current trajectory hits it in time</li><li><strong>Monthly income</strong> — user sets desired monthly passive income in retirement; app back-calculates the required portfolio size and whether they&#39;re on track</li><li><strong>4% rule</strong> — app auto-calculates the required portfolio as 25× annual expenses (from Settings); shows on-track / off-track status</li></ol><p>Each view shows: required amount, projected amount at target date, gap (if any), and an on-track / off-track indicator.</p><h3 id="projection-curves" tabindex="-1">Projection Curves <a class="header-anchor" href="#projection-curves" aria-label="Permalink to &quot;Projection Curves&quot;">​</a></h3><ul><li>Three scenarios: Conservative, Moderate, Aggressive</li><li>Default return rates configurable per account type (stocks, crypto, real estate, cash/savings, retirement accounts)</li><li>Chart shows projected total value year by year through the target retirement date and 20 years beyond (to illustrate post-retirement sustainability)</li></ul><h3 id="contributions" tabindex="-1">Contributions <a class="header-anchor" href="#contributions" aria-label="Permalink to &quot;Contributions&quot;">​</a></h3><ul><li>Per-account monthly contribution input</li><li>Contributions factored into all three scenario curves</li></ul><hr><h2 id="_6-insights" tabindex="-1">6. Insights <a class="header-anchor" href="#_6-insights" aria-label="Permalink to &quot;6. Insights&quot;">​</a></h2><h3 id="card-grid" tabindex="-1">Card Grid <a class="header-anchor" href="#card-grid" aria-label="Permalink to &quot;Card Grid&quot;">​</a></h3><p>One card per insight, color-coded by category:</p><ul><li>Risk / Performance / Tax Efficiency / Liquidity / Trends / Real Estate</li></ul><h3 id="priority-tiers" tabindex="-1">Priority Tiers <a class="header-anchor" href="#priority-tiers" aria-label="Permalink to &quot;Priority Tiers&quot;">​</a></h3><ul><li><strong>High-priority:</strong> Concrete recommended action included (&quot;what to do about it&quot;)</li><li><strong>Low-priority:</strong> Flags the issue only, no prescribed action</li></ul><h3 id="tax-efficiency-prioritized" tabindex="-1">Tax Efficiency (prioritized) <a class="header-anchor" href="#tax-efficiency-prioritized" aria-label="Permalink to &quot;Tax Efficiency (prioritized)&quot;">​</a></h3><ul><li>Asset placement recommendations: bonds in taxable, growth assets in Roth, etc.</li><li>Surfaces opportunities specific to user&#39;s jurisdiction (from Settings &gt; location)</li><li>High-priority tier — always includes recommended action</li></ul><h3 id="claude-api-chat-opt-in" tabindex="-1">Claude API Chat (opt-in) <a class="header-anchor" href="#claude-api-chat-opt-in" aria-label="Permalink to &quot;Claude API Chat (opt-in)&quot;">​</a></h3><ul><li>Appears at bottom of Insights page</li><li>Requires <code>CLAUDE_API_KEY</code> in <code>.env</code></li><li>Full portfolio data passed as context (balances, holdings, account types, user profile)</li><li>User profile context: tax filing status, income bracket, location, business info, goals</li><li>User can ask anything: &quot;Am I too heavy in tech?&quot;, &quot;What should I do before year-end?&quot;</li></ul><hr><h2 id="_7-debt" tabindex="-1">7. Debt <a class="header-anchor" href="#_7-debt" aria-label="Permalink to &quot;7. Debt&quot;">​</a></h2><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><ul><li>Hero: total debt balance + rate of change (shrinking/growing)</li><li>Debt-free date at current pace</li><li>Debt-to-income ratio (uses income from Settings &gt; user profile)</li></ul><h3 id="debt-types-tracked" tabindex="-1">Debt Types Tracked <a class="header-anchor" href="#debt-types-tracked" aria-label="Permalink to &quot;Debt Types Tracked&quot;">​</a></h3><p>All: loans (student, auto, mortgage), credit cards, lines of credit, buy-now-pay-later</p><h3 id="per-debt-card" tabindex="-1">Per-Debt Card <a class="header-anchor" href="#per-debt-card" aria-label="Permalink to &quot;Per-Debt Card&quot;">​</a></h3><ul><li>Balance, interest rate, minimum payment, payoff date</li><li>Total interest paid if minimums only</li><li>&quot;What if I pay $X extra/month&quot; calculator (inline, interactive)</li></ul><h3 id="payoff-strategy-section" tabindex="-1">Payoff Strategy Section <a class="header-anchor" href="#payoff-strategy-section" aria-label="Permalink to &quot;Payoff Strategy Section&quot;">​</a></h3><ul><li><strong>Avalanche</strong> (highest interest first) and <strong>Snowball</strong> (smallest balance first) shown side by side</li><li>Each shows: payoff order, total interest paid, debt-free date</li><li>User can compare and choose</li></ul><hr><h2 id="_8-taxes" tabindex="-1">8. Taxes <a class="header-anchor" href="#_8-taxes" aria-label="Permalink to &quot;8. Taxes&quot;">​</a></h2><h3 id="purpose-1" tabindex="-1">Purpose <a class="header-anchor" href="#purpose-1" aria-label="Permalink to &quot;Purpose&quot;">​</a></h3><p>Full tax picture: running estimate of what you owe + how to reduce it. Jurisdiction-aware using location and user profile.</p><h3 id="current-year-view-hero" tabindex="-1">Current Year View (Hero) <a class="header-anchor" href="#current-year-view-hero" aria-label="Permalink to &quot;Current Year View (Hero)&quot;">​</a></h3><ul><li>Running estimate of federal + state tax liability for the current calendar year</li><li>Broken down by income type: W-2, 1099/self-employment, capital gains (short/long), dividends, rental income, crypto</li><li>Updates automatically as new transactions are imported</li></ul><h3 id="prior-years" tabindex="-1">Prior Years <a class="header-anchor" href="#prior-years" aria-label="Permalink to &quot;Prior Years&quot;">​</a></h3><ul><li>Collapsed/accordion section below current year</li><li>Each prior year shows: summary of income types, estimated liability, transactions used</li></ul><h3 id="tax-loss-harvesting" tabindex="-1">Tax-Loss Harvesting <a class="header-anchor" href="#tax-loss-harvesting" aria-label="Permalink to &quot;Tax-Loss Harvesting&quot;">​</a></h3><ul><li>Proactive insight card on the Insights page flags opportunities</li><li>Full detail section on the Taxes page: holdings with unrealized losses, estimated tax savings if harvested, wash-sale warning</li></ul><h3 id="entity-structure-recommendations" tabindex="-1">Entity Structure Recommendations <a class="header-anchor" href="#entity-structure-recommendations" aria-label="Permalink to &quot;Entity Structure Recommendations&quot;">​</a></h3><p>Powered by user profile (income, business activity, location):</p><ul><li>Recommendation: which structure fits (sole prop → LLC → S-Corp, etc.)</li><li>Plain-English explanation of why it fits their situation</li><li>Estimated annual tax savings vs current structure</li><li>Setup checklist: actionable steps to make the switch</li></ul><h3 id="jurisdiction-awareness" tabindex="-1">Jurisdiction Awareness <a class="header-anchor" href="#jurisdiction-awareness" aria-label="Permalink to &quot;Jurisdiction Awareness&quot;">​</a></h3><ul><li>Uses <code>country</code> + <code>state</code> from Settings &gt; user profile</li><li>Surfaces state-specific rules (e.g. no state income tax states, community property rules, etc.)</li></ul><hr><h2 id="_9-settings" tabindex="-1">9. Settings <a class="header-anchor" href="#_9-settings" aria-label="Permalink to &quot;9. Settings&quot;">​</a></h2><h3 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h3><p><strong>User Profile</strong> (used across the whole app for personalized guidance)</p><ul><li>Name</li><li>Date of birth (used for age-based projections)</li><li>Country + state/province (jurisdiction for tax law, real estate regulations)</li><li>Tax filing status (single, married filing jointly, etc.)</li><li>Estimated annual income (W-2, 1099/self-employment, rental — separate fields)</li><li>Business entity (none / sole prop / LLC / S-Corp / other)</li><li>Risk profile (conservative / moderate / aggressive)</li><li>Monthly expenses (used for liquidity and 4% rule calculations)</li></ul><p><strong>Accounts &amp; Institutions</strong></p><ul><li>Manage institutions: add, edit export URL, view/reset column mapping</li><li>Quick access also available from Import page</li><li>Manage accounts: add, rename, delete, assign institution</li></ul><p><strong>Import</strong></p><ul><li>Watch folder path</li><li>Import notification mode: toast (default) vs silent auto-import toggle</li></ul><p><strong>API Keys</strong></p><ul><li><code>NEWS_API_KEY</code> — for NewsAPI news feed</li><li><code>CLAUDE_API_KEY</code> — for Insights chat and tax/entity recommendations</li><li>Both stored in <code>.env</code>, never committed to git</li><li>Settings page shows masked value + &quot;configured / not configured&quot; status</li></ul><p><strong>Retirement</strong></p><ul><li>Per-account-type return rates (conservative / moderate / aggressive)</li></ul><p><strong>Data &amp; Backups</strong></p><ul><li>Export all data: JSON, CSV per account</li><li>Versioned date-stamped backups — list of all checkpoints with restore button</li><li>Rolling back restores the full database to that checkpoint</li></ul><p><strong>System</strong></p><ul><li>Manual &quot;Refresh prices&quot; button</li><li>Watch folder status indicator</li></ul><hr><h2 id="data-model-additions" tabindex="-1">Data Model Additions <a class="header-anchor" href="#data-model-additions" aria-label="Permalink to &quot;Data Model Additions&quot;">​</a></h2><p>The following fields are needed beyond ADR-001:</p><h3 id="user-profile-settings-keys-in-settings-table" tabindex="-1"><code>user_profile</code> settings keys (in <code>settings</code> table) <a class="header-anchor" href="#user-profile-settings-keys-in-settings-table" aria-label="Permalink to &quot;`user_profile` settings keys (in `settings` table)&quot;">​</a></h3><ul><li><code>dob</code> — date of birth</li><li><code>country</code> — country of residence</li><li><code>state</code> — state/province</li><li><code>tax_filing_status</code> — single / mfj / mfs / hoh</li><li><code>income_w2</code> — annual W-2 income estimate</li><li><code>income_1099</code> — annual 1099/self-employment income estimate</li><li><code>income_rental</code> — annual rental income estimate</li><li><code>business_entity</code> — none / sole_prop / llc / s_corp / other</li><li><code>monthly_expenses</code> — already in ADR-001</li><li><code>risk_profile</code> — already in ADR-001</li><li><code>retirement_target_age</code> — user-configured target retirement age</li><li><code>retirement_target_amount</code> — optional fixed number target</li><li><code>retirement_monthly_income_target</code> — optional monthly income target</li></ul><h3 id="backups-table" tabindex="-1"><code>backups</code> table <a class="header-anchor" href="#backups-table" aria-label="Permalink to &quot;`backups` table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>id</td><td>INTEGER PK</td><td></td></tr><tr><td>created_at</td><td>DATETIME</td><td></td></tr><tr><td>label</td><td>TEXT</td><td>Auto-generated: &quot;2026-04-05 14:32&quot;</td></tr><tr><td>file_path</td><td>TEXT</td><td>Path to <code>.db</code> snapshot file</td></tr><tr><td>size_bytes</td><td>INTEGER</td><td></td></tr></tbody></table><h3 id="news-cache-table" tabindex="-1"><code>news_cache</code> table <a class="header-anchor" href="#news-cache-table" aria-label="Permalink to &quot;`news_cache` table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>id</td><td>INTEGER PK</td><td></td></tr><tr><td>fetched_at</td><td>DATETIME</td><td></td></tr><tr><td>source</td><td>TEXT</td><td>rss / newsapi</td></tr><tr><td>title</td><td>TEXT</td><td></td></tr><tr><td>url</td><td>TEXT</td><td></td></tr><tr><td>published_at</td><td>DATETIME</td><td></td></tr><tr><td>symbols</td><td>JSON</td><td>Array of tickers mentioned</td></tr><tr><td>categories</td><td>JSON</td><td>Array of categories</td></tr></tbody></table><hr><h2 id="environment-variables-env-gitignored" tabindex="-1">Environment Variables (<code>.env</code>, gitignored) <a class="header-anchor" href="#environment-variables-env-gitignored" aria-label="Permalink to &quot;Environment Variables (`.env`, gitignored)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NEWS_API_KEY=your_key_here</span></span>\n<span class="line"><span>CLAUDE_API_KEY=your_key_here</span></span></code></pre></div><hr><h2 id="security-notes" tabindex="-1">Security Notes <a class="header-anchor" href="#security-notes" aria-label="Permalink to &quot;Security Notes&quot;">​</a></h2><ul><li><code>.env</code> is gitignored — never committed</li><li>API keys never stored in SQLite DB or any committed file</li><li>Settings page shows masked key values only</li></ul>',124)])])}const g=t(o,[["render",s]]);export{p as __pageData,g as default};
